import math
N, avgdl, k1, b = 1000, 20.0, 1.2, 0.75
df = {"cheap": 200, "flights": 50}

def idf(t):
    n = df[t]
    return math.log(1 + (N - n + 0.5) / (n + 0.5))

def bm25(query, tf, dl):
    K = k1 * ((1 - b) + b * dl / avgdl)
    score = 0.0
    for t in query:
        f = tf.get(t, 0)
        if f == 0:
            continue
        score += idf(t) * f / (f + K)
    return score

print(round(bm25(["cheap", "flights"], {"cheap": 2, "flights": 3}, 60), 2))

import math
from collections import Counter, defaultdict

class BM25:
    def __init__(self, docs, k1=1.2, b=0.75):
        self.k1, self.b = k1, b
        self.postings = defaultdict(list)          # term -> [(doc, tf)]
        self.dl = [len(d) for d in docs]
        for i, d in enumerate(docs):
            for t, f in Counter(d).items():
                self.postings[t].append((i, f))
        self.N = len(docs)
        self.avgdl = sum(self.dl) / self.N

    def idf(self, t):                              # Lucene's IDF
        n = len(self.postings.get(t, []))
        return math.log(1 + (self.N - n + 0.5) / (n + 0.5))

    def search(self, query, k=10):
        scores = defaultdict(float)                # doc -> score
        for t in query:
            w = self.idf(t)
            for d, f in self.postings.get(t, []):  # only docs with t
                K = self.k1 * (1 - self.b + self.b * self.dl[d] / self.avgdl)
                scores[d] += w * f / (f + K)
        return sorted(scores.items(), key=lambda x: -x[1])[:k]
